import * as React from "react";
import { Box, Button, Typography } from "@mui/material";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableHead from "@mui/material/TableHead";
import TableContainer from "@mui/material/TableContainer";
import TableRow from "@mui/material/TableRow";
import { URL } from "../../../URL";
import { useSelector } from "react-redux";
import { Stack } from "@mui/system";
import ChevronLeftIcon from "@mui/icons-material/ChevronLeft";
import NavigateNextIcon from "@mui/icons-material/NavigateNext";
import { fetchAlluser } from "../../../Api/api";
import { useDispatch } from "react-redux";
import { Allusers } from "../../../Redux/Reducer";
import { NavLink } from "react-router-dom";
export default function ViewTable() {
  const dispatch = useDispatch();
  const { ceilSlice } = useSelector((state) => state);
  let { allusers } = ceilSlice;
  //.....pagniations ......
  let { users, totalPages, currentPage } = allusers;
  const [totalpage, setTotalpage] = React.useState(totalPages || 0);
  const [page, setPage] = React.useState(currentPage || 0);

  //....fetch all users.....
  const fetchAllusers = async (page) => {
    let alluser = await fetchAlluser(page);
    dispatch(Allusers(alluser));
  };
  React.useEffect(() => {
    fetchAllusers(page);
  }, [page]);

  //...Pagniations here.........

  let menuItems = [];
  for (var i = 1; i <= totalpage; i++) {
    menuItems.push(i);
  }
  const paginationsHandles = (pages) => {
    fetchAllusers(pages);
    setPage(pages);
  };
  const PreviousButton = () => {
    setPage((page) => page - 1);
  };
  const NextButton = () => {
    setPage((page) => page + 1);
  };
  return (
    <>
      <Box
        sx={{
          my: 5,
          boxShadow: 2,
          backgroundColor: "background.secondary",
          borderRadius: "10px",
        }}
      >
        <TableContainer sx={{ p: 2 }}>
          <Table sx={{ minWidth: 850 }} aria-label="custom pagination table">
            <TableHead>
              <TableRow>
                <TableCell
                  align="left"
                  sx={{ fontWeight: "700", fontSize: "12px" }}
                >
                  User Name
                </TableCell>

                <TableCell
                  align="left"
                  sx={{ fontWeight: "700", fontSize: "12px" }}
                >
                  Email
                </TableCell>
                <TableCell
                  align="left"
                  sx={{ fontWeight: "700", fontSize: "12px" }}
                >
                  NFTS
                </TableCell>
                {/* <TableCell
                align="left"
                sx={{ fontWeight: "700", fontSize: "12px" }}
              >
                Status
              </TableCell> */}
                <TableCell
                  align="left"
                  sx={{ fontWeight: "700", fontSize: "12px" }}
                >
                  Address
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {users?.length > 0 &&
                users.map(({ email, profileImage, username, _id, wallet }) => (
                  <TableRow key={_id}>
                    <TableCell style={{ minWidth: 120 }} align="left">
                      <Box
                        sx={{
                          display: "flex",
                          justifyContent: "flex-start",
                          alignItems: "center",
                        }}
                      >
                        <img
                          src={
                            profileImage
                              ? `${URL}/upload/${profileImage}`
                              : "https://pbs.twimg.com/media/FhC3LvHXkAEMEUZ.png"
                          }
                          alt=""
                          srcSet=""
                          style={{ borderRadius: "8px", width: "40px" }}
                        />
                        <Box sx={{ ml: 2 }}>
                          <Typography sx={{ fontSize: "14px" }}>
                            {username}
                          </Typography>
                        </Box>
                      </Box>
                    </TableCell>
                    <TableCell
                      sx={{ minWidth: 120, color: "text.secondary" }}
                      align="left"
                    >
                      {email}
                    </TableCell>
                    <TableCell
                      sx={{ minWidth: 120, color: "text.secondary" }}
                      align="left"
                    >
                      5
                    </TableCell>
                    {/* <TableCell
                    sx={{ minWidth: 120, color: "text.secondary" }}
                    align="left"
                  >
                    pandding
                  </TableCell> */}
                    <TableCell sx={{ minWidth: 130, color: "text.secondary" }}>
                      {wallet}
                    </TableCell>
                    <TableCell style={{ minWidth: 20 }} align="left">
                      ...
                    </TableCell>
                  </TableRow>
                ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Box>
      <Box sx={{ m: 1, mb: 2 }}>
        <Stack direction={"row"} alignItems="right" justifyContent="center">
          {page === 1 ? (
            <Button
              startIcon={<ChevronLeftIcon />}
              sx={{
                width: "20px",
                background:
                  "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                color: "white",
                "&:hover": {
                  background:
                    "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                },
              }}
              disabled
            />
          ) : (
            <Button
              onClick={() => {
                PreviousButton();
              }}
              startIcon={<ChevronLeftIcon />}
              sx={{
                width: "20px",
                background:
                  "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                color: "white",
                "&:hover": {
                  background:
                    "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                },
              }}
            />
          )}

          {menuItems?.length > 0 &&
            menuItems.map((items, index) => {
              return (
                <Button
                  sx={{ width: "20px" }}
                  key={index}
                  onClick={() => {
                    paginationsHandles(index + 1);
                  }}
                >
                  {index + 1}
                </Button>
              );
            })}
          {page !== totalPages ? (
            <Button
              // component={<NavLink />}
              to="#"
              onClick={() => {
                NextButton();
              }}
              startIcon={<NavigateNextIcon />}
              sx={{
                width: "20px",
                background:
                  "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                color: "white",
                "&:hover": {
                  background:
                    "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                },
              }}
            />
          ) : (
            <Button
              startIcon={<NavigateNextIcon />}
              sx={{
                width: "20px",
                background:
                  "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                color: "white",
                "&:hover": {
                  background:
                    "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                },
              }}
              disabled
            />
          )}
        </Stack>
      </Box>
    </>
  );
}
