import React, { useContext } from "react";
import { Box, Typography, InputAdornment } from "@mui/material";
import earth from "../../images/earth.png";
import { Link, useNavigate } from "react-router-dom";
import TextField from "@mui/material/TextField";
import { toast } from "react-toastify";
import { useFormik } from "formik";
import * as yup from "yup";
import { loginUser } from "../../Api/api";
import CustomBTN from "../CustomButton/CustomBTN";
import { useDispatch } from "react-redux";
import { Adduser } from "../../Redux/Reducer";
import VisibilityIcon from "@mui/icons-material/Visibility";
import VisibilityOffIcon from "@mui/icons-material/VisibilityOff";
import { WalletContextProvider } from "../../ContextAPI/CreateContext";
import bg from "../../images/bg.png";
import { useState } from "react";
const validationSchema = yup.object({
  email: yup
    .string("Enter your email")
    .email("Enter a valid email")
    .required("Email is required"),
  password: yup
    .string("Enter your password")
    .min(8, "Password should be of minimum 8 characters length")
    .required("Password is required"),
});

export const Login = () => {
  const dispatch = useDispatch();
  const { address } = useContext(WalletContextProvider);
  const navigate = useNavigate();
  const [toggle, setToggle] = useState(false);
  const loginHandle = async (values) => {
    try {
      console.log("values wallet address:", values);
      const data = await loginUser(values);
      if (data?.status === "ok") {
        console.log("login user:", data?.data);
        dispatch(Adduser(data?.data));
        toast.success(data?.message);
        localStorage.setItem("maptoken", data.token);
        setTimeout(() => {
          navigate("/");
        }, 2000);
      }
      data?.status === "error" && toast.error(data.message);
    } catch (err) {
      console.log("Error in login User", err);
    }
  };
  const formik = useFormik({
    initialValues: {
      email: "",
      password: "",
    },

    validationSchema: validationSchema,
    onSubmit: async (values) => {
      loginHandle(values);
    },
  });

  return (
    <>
      <Box
        sx={{
          backgroundImage: `url(${earth})`,
          height: "100vh",
          width: "100%",
          position: "center",
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
          display: "flex",
          alignItems: "start",
        }}
      >
        <Box
          sx={{
            display: "flex",
            flexDirection: { xs: "column", sm: "column", md: "row" },
            width: { xs: "90%", md: "80%", lg: "60%" },
            marginX: "auto",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box
            sx={{
              width: { xs: "90%", sm: "90%", md: "50%",  },
              marginX: "auto",
              backgroundImage: `url(${bg})`,
              backgroundSize: "100% 100%",
              mt: 15,
              color: "white",
              padding: { xs: "15px", sm: "10px", md: "20px", lg: "30px" },
            }}
          >
            <Typography variant="h5" textAlign="center" fontWeight="bold">
              Welcome to the NFT Land !
            </Typography>
            <Typography
              variant="h4"
              textAlign="center"
              fontWeight="bold"
              sx={{ marginY: "20px" }}
            >
              LOGIN
            </Typography>
            <form>
              <Box>
                <Typography variant="body2">EMAIL ADDRESS</Typography>
                <TextField
                  fullWidth
                  type="email"
                  placeholder="Email"
                  name="email"
                  autoComplete="off"
                  value={formik.values.email}
                  onChange={formik.handleChange}
                  error={formik.touched.email && Boolean(formik.errors.email)}
                  helperText={formik.touched.email && formik.errors.email}
                  sx={(theme) => ({
                    backgroundColor:
                      theme.palette.mode === "light" ? "#F8F5F5" : "#262626",
                    borderRadius: "8px",
                    border: "none",
                    input: {
                      color:
                        theme.palette.mode === "light" ? "#00000" : "#ffffff",
                    },
                  })}
                />
              </Box>
              <Box my={3}>
                <Typography variant="body2">PASSWORD</Typography>

                <TextField
                  fullWidth
                  placeholder="Password"
                  name="password"
                  type={toggle ? "text" : "password"}
                  value={formik.values.password}
                  onChange={formik.handleChange}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment
                        sx={{ cursor: "pointer",backgroundColor:"background.inputbg" }}
                        position="end"
                        onClick={() => {
                          setToggle(!toggle);
                        }}
                      >
                        {toggle ? <VisibilityOffIcon /> : <VisibilityIcon />}
                      </InputAdornment>
                    ),
                  }}
                  error={
                    formik.touched.password && Boolean(formik.errors.password)
                  }
                  helperText={formik.touched.password && formik.errors.password}
                  sx={(theme) => ({
                    backgroundColor:
                      theme.palette.mode === "light" ? "#F8F5F5" : "#262626",
                    borderRadius: "8px",
                    border: "none",
                    input: {
                      color:
                        theme.palette.mode === "light" ? "#00000" : "#ffffff",
                    },
                  })}
                />
              </Box>
              <Box
                onClick={formik.handleSubmit}
                sx={{
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  mt: 2,
                }}
              >
                <CustomBTN text="Login" />
              </Box>
            </form>

            <Box
              component={Link}
              to="/register"
              sx={{
                display: "flex",
                color: "white",
                fontSize: "20px",
                justifyContent: "center",
                mt: 2,
              }}
            >
              Register Instead?
            </Box>
          </Box>
          <Box
            onClick={() => {
              !address
                ? toast.error("please connect with wallet !")
                : loginHandle({ address });
            }}
            sx={{
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              mt: 2,
            }}
          >
            <CustomBTN text="Login with Wallet" />
          </Box>
        </Box>
      </Box>
    </>
  );
};
