import * as React from "react";
import {
  Box,
  IconButton,
  InputBase,
  Typography,
  Dialog,
  Button,
  Slide,
  Stack,
  Select,
  MenuItem,
  Paper,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import { useForm } from "react-hook-form";
import { useDropzone } from "react-dropzone";
import CloudUploadIcon from "@mui/icons-material/CloudUpload";
import styled from "@emotion/styled";
import { updateNfts } from "../../../Api/api";
import { toast } from "react-toastify";
import CustomBTN from "../../CustomButton/CustomBTN";
import AddIcon from "@mui/icons-material/Add";
const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="down" ref={ref} {...props} />;
});
const thumbsContainer = {
  display: "flex",
  flexDirection: "row",
  flexWrap: "wrap",
  marginTop: 16,
};
const thumbInner = {
  display: "flex",
  minWidth: 0,
  overflow: "hidden",
};

const img = {
  display: "block",
  width: "auto",
  height: "100%",
};
const thumb = {
  display: "inline-flex",
  borderRadius: 2,
  marginBottom: 8,
  marginRight: 8,
  width: "auto",
  height: 200,
  boxSizing: "border-box",
};

const StyledMenuItem = styled(MenuItem)({
  backgroundColor: "background.inputbg",
  margin: "5px",
  borderRadius: "5px",
});

export default function EditProduct(props) {
  const [openModal, setOpenModal] = React.useState(props?.open);
  const [files, setFiles] = React.useState([]);
  const [fileType, setFileType] = React.useState("File");
  const [NFtfile, setNftfiles] = React.useState("");

  const [addMore, setAddMore] = React.useState({
    question: "",
    answers: [],
  });
  const [addans, setAnsState] = React.useState({ id: "" });
  const [inputstate, setInputstate] = React.useState([]);
  const addQuestions = () => {
    if (inputstate.length < 10) {
      setInputstate([...inputstate, { id: inputstate.length }]);
    }
  };
  // //......Add more metadata.......
  // const addAnsHandler = (e) => {
  //   console.log(e, "events");
  //   const key = e.target.name;
  //   console.log("key", key, "value:", e.target.value);
  //   setAnsState({ ...addans, [key]: e.target.value });
  // };
  const form = new FormData();
  const {
    _id,
    address,
    addressdetails,
    productTotalPrice,
    fileLink,
    description,
    name,
    mapaddress,
  } = props?.nftsDetails;

  const { getRootProps, getInputProps, open } = useDropzone({
    accept: "image/*",
    noClick: true,
    noKeyboard: true,
    onDrop: (acceptedFiles) => {
      console.log("acceptedFiles:", acceptedFiles);

      setNftfiles(acceptedFiles[0]);
      setFiles(
        acceptedFiles.map((file) =>
          Object.assign(file, {
            preview: URL.createObjectURL(file),
          })
        )
      );
    },
  });
  const thumbs = files.map((file) => (
    <div style={thumb} key={file.name}>
      <div style={thumbInner}>
        <img src={file.preview} style={img} alt="" />
      </div>
    </div>
  ));

  const {
    register,
    handleSubmit,
    setValue,
    formState: { errors },
  } = useForm({ mode: "onChange" });

  // .......set Image in useHook Form.........
  React.useEffect(() => {
    setValue("filelink", fileLink ? fileLink : "");
    setValue("name", name);
    setValue("productTotalPrice", productTotalPrice);
    setValue("mapaddress", mapaddress);
    setValue("addressdetails", addressdetails);
    setValue("description", description);
  }, []);

  const handleClose = () => {
    setOpenModal(false);
    props.modalFunc(false);
  };

  const onSubmit = async (data, e) => {
    for (let key in data) {
      form.append(key, data[key]);
    }
    form.append("file", NFtfile);
    form.append("_id", _id);
    form.append("walletAddress", address);
    try {
      const data = await updateNfts(form);
      if (data.status === "ok") {
        toast.success("Nft Data update successfully !");
        setTimeout(() => {
          props.modalFunc(false);
        }, 2000);
      } else {
        toast.error(data?.message);
      }
    } catch (error) {
      console.log("Nfts update error", error);
    }
  };

  return (
    <Paper>
      <Dialog
        TransitionComponent={Transition}
        open={openModal}
        onClose={() => {
          handleClose();
        }}
        maxWidth="xs"
        fullWidth
        sx={{
          "& .css-twia2z-MuiPaper-root-MuiDialog-paper": {
            borderRadius: "10px",
            background: "background.secondary",
          },
        }}
      >
        <Box p={2} component="form" onSubmit={handleSubmit(onSubmit)}>
          <Box display="flex" justifyContent="end">
            <IconButton
              onClick={() => {
                handleClose();
              }}
              sx={{ float: "right", color: "text.seconary" }}
            >
              <CloseIcon />
            </IconButton>
          </Box>
          {fileType === "File" && (
            <Box
              display="flex"
              alignItems="center"
              flexDirection="column"
              {...getRootProps()}
            >
              <input {...getInputProps()} />
              {files?.length > 0 ? (
                <aside style={thumbsContainer}>{thumbs}</aside>
              ) : (
                <Stack
                  alignItems="center"
                  sx={{ py: 3, color: "text.secondary", cursor: "pointer" }}
                  onClick={() => {
                    open();
                  }}
                >
                  <CloudUploadIcon fontSize="large" />
                  <Typography
                    sx={{
                      fontWeight: "600",
                      fontSize: "18px",
                    }}
                  >
                    Browse Files
                  </Typography>
                  <Typography
                    sx={{
                      fontWeight: "600",
                      fontSize: "14px",
                    }}
                  >
                    Drag and drop files here
                  </Typography>
                </Stack>
              )}
              {/* {files?.length > 0 && (
                <IconButton
                  onClick={open}
                  color="primary"
                  aria-label="upload picture"
                  component="label"
                  sx={{ color: "#ffffff" }}
                >
                  <PhotoCamera />
                  <Typography
                    sx={{
                      pl: 1,
                   
                      fontSize: "14px",
                      fotWeight: "700",
                    }}
                  >
                    Upload image
                  </Typography>
                </IconButton>
              )} */}
            </Box>
          )}

          <Box py={1}>
            <Typography sx={{ color: "text.primery" }}>Type </Typography>
            <Select
              sx={{
                height: "39px",
                borderRadius: "5px",
                backgroundColor: "background.inputbg",
                "& .MuiOutlinedInput-notchedOutline": {
                  border: "none",
                },
              }}
              value={fileType}
              onChange={(e) => setFileType(e.target.value)}
              fullWidth
              inputProps={{
                MenuProps: {
                  MenuListProps: {},
                },
              }}
            >
              <StyledMenuItem value="File">File</StyledMenuItem>
              <StyledMenuItem value="Link">Link</StyledMenuItem>
            </Select>
          </Box>
          {fileType === "Link" && (
            <Box py={1}>
              <Typography sx={{}}>Link </Typography>
              <InputBase
                // {...register("filelink", { required: true })}
                placeholder="Enter link"
                type="text"
                sx={{
                  backgroundColor: "background.inputbg",
                  width: "100%",
                  borderRadius: "5px",
                  px: 2,
                  py: 0.5,
                }}
              />
              {/* {errors.filelink && (
                <Typography sx={{ fontSize: "14px", color: "red" }}>
                  This field is required *
                </Typography> */}
              {/* )} */}
            </Box>
          )}
          <Box py={1}>
            <Typography>Title </Typography>
            <InputBase
              {...register("name", { required: true })}
              placeholder="Enter title"
              type="text"
              sx={{
                backgroundColor: "background.inputbg",
                width: "100%",
                borderRadius: "5px",
                px: 2,
                py: 0.5,
              }}
            />
            {errors.name && (
              <Typography sx={{ color: "red", fontSize: "14px" }}>
                This field is required *
              </Typography>
            )}
          </Box>
          <Box py={1}>
            <Typography>Price</Typography>
            <InputBase
              {...register("productTotalPrice", { required: true })}
              placeholder="Enter Price"
              type="text"
              sx={{
                backgroundColor: "background.inputbg",
                color: "gray",
                width: "100%",
                borderRadius: "5px",
                px: 2,
                py: 0.5,
              }}
            />
            {errors.productTotalPrice && (
              <Typography sx={{ color: "red", fontSize: "14px" }}>
                This field is required *
              </Typography>
            )}
          </Box>
          <Box py={1}>
            <Typography>Description</Typography>
            <InputBase
              {...register("description", { required: true })}
              placeholder="Enter description"
              type="text"
              sx={{
                backgroundColor: "background.inputbg",
                width: "100%",
                borderRadius: "5px",
                px: 2,
                py: 0.5,
              }}
            />
            {errors.description && (
              <Typography sx={{ color: "red", fontSize: "14px" }}>
                This field is required *
              </Typography>
            )}
          </Box>
          <Box py={1}>
            <Typography>Address</Typography>
            <InputBase
              {...register("mapaddress", { required: true })}
              placeholder="Enter address"
              type="text"
              sx={{
                backgroundColor: "background.inputbg",
                width: "100%",
                borderRadius: "5px",
                px: 2,
                py: 0.5,
              }}
            />
            {errors.mapaddress && (
              <Typography sx={{ color: "red", fontSize: "14px" }}>
                This field is required *
              </Typography>
            )}
          </Box>
          <Box py={1}>
            <Typography>Address details *</Typography>
            <InputBase
              {...register("addressdetails", { required: true })}
              multiline
              minRows={2}
              placeholder="Enter address details"
              type="text"
              sx={{
                backgroundColor: "background.inputbg",
                width: "100%",
                borderRadius: "5px",
                px: 2,
                py: 0.5,
              }}
            />
          </Box>
          {inputstate?.length > 0
            ? inputstate?.map(({ id }, index) => {
                return (
                  <Box py={1} key={index + Math.random() * 10}>
                    <Typography>Metadata *</Typography>
                    <InputBase
                      {...register(`matadata${id}`)}
                      multiline
                      minRows={2}
                      placeholder="Enter matadata"
                      type="text"
                      sx={{
                        backgroundColor: "background.inputbg",
                        width: "100%",
                        borderRadius: "5px",
                        px: 2,
                        py: 0.5,
                      }}
                    />
                  </Box>
                );
              })
            : ""}
          <Box
            sx={{
              width: "50%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
            }}
            onClick={() => {
              addQuestions();
            }}
          >
            <CustomBTN text="Add MetaData" />
          </Box>
          <Box py={1} display="flex" justifyContent="center">
            <Button
              type="submit"
              sx={{
                mt: 2,
                fontSize: "15px",
                width: "100%",
                borderRadius: "5px",
                background:
                  " linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                color: "white",
                fontWeight: 700,
                boxShadow: 2,
              }}
            >
              Edit
            </Button>
          </Box>
        </Box>
      </Dialog>
    </Paper>
  );
}
