import { Box, Button, Hidden, IconButton, Paper, Tooltip } from "@mui/material";
import KeyboardBackspaceIcon from "@mui/icons-material/KeyboardBackspace";
import React from "react";
import { useNavigate } from "react-router-dom";
import auther from "../../images/auther.PNG";

import EditIcon from "@mui/icons-material/Edit";
import PopUp from "../userDashbord/userWallet/popup";
import EditProfile from "../userDashbord/profile/EditeProfile";
import { useSelector } from "react-redux";

import { URL } from "../../URL";
import FacebookIcon from "@mui/icons-material/Facebook";
import InstagramIcon from "@mui/icons-material/Instagram";
import TwitterIcon from "@mui/icons-material/Twitter";
import LinkedInIcon from "@mui/icons-material/LinkedIn";
const bannerstyle = {
  height: "300px",
  width: "100%",
  borderRadius: "10px",
  marginTop: "20px",
  background: "cover",
  position: "center",
};

const array = [
  {
    name: "Facebook",

    icon: <FacebookIcon />,
  },
  {
    name: "Instagram",

    icon: <InstagramIcon />,
  },
  {
    name: "Twitter",

    icon: <TwitterIcon />,
  },
  {
    name: "LinkedIn",

    icon: <LinkedInIcon />,
  },
];

export const AdminHeader = () => {
  const [open, setOpen] = React.useState(false);
  const { ceilSlice } = useSelector((state) => state);
  const { userdetails } = ceilSlice;
  function modalClose(value) {
    setOpen(value);
  }
  const navigate = useNavigate();
  return (
    <>
      {open && <EditProfile open={open} modalFunc={modalClose} />}
      <Box sx={{ width: "100%", mx: "auto", mt: { xs: 1, md: 15 } }}>
        <Button
          onClick={() => {
            navigate(-1);
          }}
          variant="outlined"
          sx={{ ml: { xs: 2, md: 5 } }}
          startIcon={<KeyboardBackspaceIcon />}
        >
          Go back
        </Button>
        <Box
          sx={{
            width: "96%",
            mx: "auto",
            display: "flex",
            justifyContent: "space-between",
            // p: 2,
            // pl: 2,
            backgroundColor: "background.secondary",
            boxShadow: 2,
            borderRadius: "10px",
          }}
        >
          <Hidden lgDown>
            <Box
              sx={{
                height: { xs: "60px", sm: "150px", lg: "250px" },
                width: { xs: "60px", sm: "150px", lg: "250px" },
                // position: "absolute",
                top: { xs: "10px", sm: "30px", md: "30px" },
                left: { xs: "10px", md: "20px" },
              }}
            >
              <img
                src={
                  userdetails?.profileImage
                    ? `${URL}/upload/${userdetails?.profileImage}`
                    : auther
                }
                alt=""
                srcSet=""
                style={{ height: "100%", width: "100%", borderRadius: "50%" }}
              />
            </Box>
          </Hidden>

          <Box
            sx={{
              display: "flex",
              width: { xs: "100%", lg: "80%" },
              // justifyContent: { xs: "flex-start", md: "flex-end" },
              flexDirection: { xs: "column", md: "row" },
              alignItems: "center",
              height: "300px",
              position: "relative",

              position: "relative",
              backgroundImage: userdetails?.banner
                ? `url(${URL}/upload/${userdetails?.banner})`
                : `url("https://img.freepik.com/free-vector/technology-earth-digital-global-background_1017-31182.jpg?w=2000")`,
              height: "300px",
              backgroundSize: "cover",
              backgroundPosition: "top",
              backgroundRepeat: "no-repeat",
              // mb: 1,
              // mr: 1,
            }}
          >
            <Hidden lgUp>
              <Box
                sx={{
                  height: { xs: "60px", sm: "150px", lg: "250px" },
                  width: { xs: "60px", sm: "150px", lg: "250px" },
                  position: "absolute",
                  top: { xs: "10px", sm: "30px", md: "20px" },
                  left: { xs: "5%", md: "3%" },
                }}
              >
                <img
                  src={
                    userdetails?.profileImage
                      ? `${URL}/upload/${userdetails?.profileImage}`
                      : auther
                  }
                  alt=""
                  srcSet=""
                  style={{ height: "100%", width: "100%", borderRadius: "50%" }}
                />
              </Box>
            </Hidden>

            <Box
              sx={{
                color: "white",
                position: "absolute",
                bottom: "0px",
                left: "0px",
                fontSize: "20px",
              }}
            >
              {array.map((item, index) => {
                return (
                  <Tooltip title={item.name} placement="top">
                    <IconButton
                      fontSize="small"
                      sx={{
                        background:
                          "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                        ml: 1,
                        mb: 1,
                        borderRadius: "5px",
                        width:"35px",
                        height:"35px"
                      }}
                    >
                      {item.icon}
                    </IconButton>
                  </Tooltip>
                );
              })}
            </Box>
            <Box
              sx={{
                position: "relative",
                width: { xs: "100%", md: "100%", lg: "75%" },
                height: { xs: "200px", md: "300px" },
              }}
            >

            </Box>
            <Box
              sx={{
                display: "flex",
                justifyContent: "flex-end",
                position: "absolute",
                bottom: "-20px",
                right: "0px",
              }}
            >
              <Box sx={{ pr: 4, display: "flex", alignItems: "center" }}>
                <Tooltip title="Edit" placement="top">
                  <IconButton
                    sx={{
                      background:
                        "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                      mr: 1,
                      mt: 1,
                      borderRadius: "5px",
                    }}
                    onClick={() => {
                      setOpen(true);
                    }}
                  >
                    <EditIcon fontSize="small" sx={{ color: "white" }} />
                  </IconButton>
                </Tooltip>
                <PopUp />
              </Box>
            </Box>
          </Box>
        </Box>
      </Box>
    </>
  );
};
