import { Box, Stack, Typography, InputAdornment } from "@mui/material";
import React, { useState, useEffect, useContext } from "react";
import earth from "../../images/earth.png";
import bg from "../../images/bg.png";
import { Link, useNavigate } from "react-router-dom";
import TextField from "@mui/material/TextField";
import { useFormik } from "formik";
import * as yup from "yup";
import { toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { registerUser } from "../../Api/api";
import CustomBTN from "../CustomButton/CustomBTN";
import VisibilityIcon from "@mui/icons-material/Visibility";
import VisibilityOffIcon from "@mui/icons-material/VisibilityOff";
import { WalletContextProvider } from "../../ContextAPI/CreateContext";
const validationSchema = yup.object({
  username: yup
    .string()
    .min(2, "Too Short!")
    .max(70, "Too Long!")
    .required("Required"),
  email: yup
    .string("Enter your email")
    .email("Enter a valid email")
    .required("Email is required"),
  password: yup
    .string("Enter your password")
    .min(8, "Password should be of minimum 8 characters length")
    .required("Password is required"),
});

//..........register function...........
export const Register = () => {
  const [toggle, setToggle] = useState(false);
  const { address } = useContext(WalletContextProvider);
  const [walletaddress, setWalletaddress] = useState("");
  console.log("address:", address, "walletaddress", walletaddress);
  const navigate = useNavigate();
  const [lat, setLat] = useState(null);
  const [lng, setLng] = useState(null);
  const getLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(showPosition);
    } else {
      console.log("Error while geting  location ... ");
    }
  };
  function showPosition(position) {
    setLat(position.coords.latitude);
    setLng(position.coords.longitude);
  }

  useEffect(() => {
    getLocation();
  }, []);
  useEffect(() => {
    setWalletaddress(address);
  }, [address]);
  const formik = useFormik({
    initialValues: {
      username: "",
      email: "",
      password: "",
    },
    validationSchema: validationSchema,

    onSubmit: async (values) => {
      try {
        const { username, email, password } = values;
        const obj = {
          username,
          email,
          password,
          wallet: walletaddress,
          latLng: [lat, lng],
        };
        console.log("obj:", obj);
        if (!address) {
          toast.error("Please connect with Wallet");
          return false;
        }

        const data = await registerUser(obj);
        if (data?.status === "ok") {
          toast.success(data?.message);
          setTimeout(() => {
            navigate("/login");
          }, 2000);
        }
        data?.status === "error" && toast.error(data?.message);
      } catch (err) {
        console.log("Error in user registration", err);
      }
    },
  });

  return (
    <>
      <Box
        sx={{
          backgroundImage: `url(${earth})`,
          minHeight: "100vh",
          width: "100%",
          position: "center",
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
          display: "flex",
          alignItems: "start",
         
        }}
      >
        <Box
          sx={{
            width: { xs: "90%", sm: "70%", md: "35%", lg: "28%" },
            marginX: "auto",
            p: 3,
            backgroundImage: `url(${bg})`,
            backgroundSize: "100% 100%",
            mt: 14,
            color: "white",
          }}
        >
          {/* <Typography variant="h5" textAlign="center" fontWeight="bold">
            Welcome to the NFt Land !
          </Typography> */}
          <Typography
            variant="h6"
            textAlign="center"
            fontWeight="bold"
            sx={{ marginY: "5px" }}
          >
            REGISTER
          </Typography>
          <Typography>
            Please connect to wallet for Register. because you cannot fill the
            text fields.
          </Typography>
          <Stack spacing={1}>
            <form>
              <Box>
                <Typography variant="body2">USERNAME</Typography>
                <TextField
                  fullWidth
                  type="text"
                  placeholder="username"
                  name="username"
                  autoComplete="off"
                  value={formik.values.username}
                  onChange={formik.handleChange}
                  error={
                    formik.touched.username && Boolean(formik.errors.username)
                  }
                  helperText={formik.touched.username && formik.errors.username}
                  sx={(theme) => ({
                    backgroundColor:
                      theme.palette.mode === "light" ? "#ffffff" : "#26292D",
                    borderRadius: "8px",
                    border: "none",
                    input: {
                      color:
                        theme.palette.mode === "light" ? "#00000" : "#ffffff",
                    },
                  })}
                />
              </Box>
              <Box my={1.5}>
                <Typography variant="body2">Wallet</Typography>
                <TextField
                  fullWidth
                  type="text"
                  placeholder="Wallet Address"
                  name="wallet"
                  autoComplete="off"
                  value={address}
                  sx={(theme) => ({
                    backgroundColor:
                      theme.palette.mode === "light" ? "#ffffff" : "#26292D",
                    borderRadius: "8px",
                    border: "none",
                    input: {
                      color:
                        theme.palette.mode === "light" ? "#00000" : "#ffffff",
                    },
                  })}
                  readOnly
                />
              </Box>
              <Box my={1.5}>
                <Typography variant="body2">EMAIL ADDRESS</Typography>
                <TextField
                  fullWidth
                  type="email"
                  placeholder="Email"
                  name="email"
                  autoComplete="off"
                  value={formik.values.email}
                  onChange={formik.handleChange}
                  error={formik.touched.email && Boolean(formik.errors.email)}
                  helperText={formik.touched.email && formik.errors.email}
                  sx={(theme) => ({
                    backgroundColor:
                      theme.palette.mode === "light" ? "#ffffff" : "#26292D",
                    borderRadius: "8px",
                    border: "none",
                    input: {
                      color:
                        theme.palette.mode === "light" ? "#00000" : "#ffffff",
                    },
                  })}
                />
              </Box>
              <Box my={1.5}>
                <Typography variant="body2">PASSWORD</Typography>

                <TextField
                  fullWidth
                  placeholder="Password"
                  name="password"
                  type={toggle ? "text" : "password"}
                  value={formik.values.password}
                  onChange={formik.handleChange}
                  error={
                    formik.touched.password && Boolean(formik.errors.password)
                  }
                  helperText={formik.touched.password && formik.errors.password}
                  sx={(theme) => ({
                    backgroundColor:
                      theme.palette.mode === "light" ? "#ffffff" : "#26292D",
                    borderRadius: "8px",
                    border: "none",
                    input: {
                      color:
                        theme.palette.mode === "light" ? "#00000" : "#ffffff",
                    },
                  })}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment
                        sx={{ cursor: "pointer" }}
                        position="end"
                        onClick={() => {
                          setToggle(!toggle);
                        }}
                      >
                        {toggle ? <VisibilityOffIcon /> : <VisibilityIcon />}
                      </InputAdornment>
                    ),
                  }}
                />
              </Box>
              <Box
                onClick={formik.handleSubmit}
                sx={{
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                <CustomBTN text="Register" />
              </Box>
            </form>
            <Box
              component={Link}
              to="/login"
              sx={{
                display: "flex",
                color: "white",
                fontSize: "20px",
                justifyContent: "center",
                mt: 2,
              }}
            >
              Login Instead?
            </Box>
          </Stack>
        </Box>
      </Box>
    </>
  );
};
