import React from "react";
import { ConnectKitButton } from "connectkit";
import { Button } from "@mui/material";
import { WalletContextProvider } from "../ContextAPI/CreateContext";
const ConnectWallet = () => {
  const [setAddress, setAddressState] = React.useState();
  const { walletAddress, address } = React.useContext(WalletContextProvider);
  React.useEffect(() => {
    walletAddress(setAddress);
  }, [setAddress]);

  return (
    <ConnectKitButton.Custom>
      {({ isConnected, isConnecting, show, hide, address, ensName }) => {
        if (isConnecting) return console.log("loading");
        if (address) setAddressState(address);
        if (!address) setAddressState("");
        return (
          <Button
            onClick={show}
            sx={{
              // position: "absolute",
              // top: "10px",
              // right: "50px",
              width: "150px",
              height: "40px",
              padding: "5px",
              float: "right",
              color: "white",
              background:
                  "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
              zIndex: 1,
              "&:hover": {
                background:
                   "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)"
              },
            }}
          >
            {isConnected
              ? address.slice(0, 4) + "..." + address.slice(-4)
              : " Connect"}
          </Button>
        );
      }}
    </ConnectKitButton.Custom>
  );
};

export default ConnectWallet;
