import React from "react";
import { Outlet } from "react-router-dom";
import { Box } from "@mui/material";
import { MainNav } from "./MainNav";
export const Sidebar = () => {
  return (
    <Box
      sx={{
        position: "relative",
        height: "100vh",
        width: "100%",
      }}
    >
      <MainNav />
      <Box sx={{ width: "100%" }}>
        <Outlet />
      </Box>
    </Box>
  );
};
